const ST_TIP = [START.c[0], node('Seed').bb[3] + 2.2], ST_DOT = [START.c[0], ST_TIP[1] + 7.0], ST_R = 1.35, ST_HEAD = headAt(ST_TIP, [0, -1], 3.0, 1.15);
