  for (let k = 0; k < out.length; k++) contour([out[k], out[(k + 1) % out.length]], { nib: 0.3, pressure: 0.9, pull: 60, profile: 'even', lose: 0, smooth: 0.05 });
  for (let k = 0; k < inn.length; k++) contour([inn[k], inn[(k + 1) % inn.length]], { nib: 0.12, pressure: 0.8, pull: 60, profile: 'even', lose: 0, smooth: 0.05 });
  P(0.12).stroke(closed(ring), { pressure: 0.75 }); P(0.15).stroke(closed(hole), { pressure: 0.85 });
