    hatchFamily(pc(C.violet), Fm, { n: 200, steps: 70, shade: sm, vis: vm, thr: 0.36, spread: 0.36, pmin: 0.38, pmax: 0.6, maxLen: 12, t0: 0.02, ph: 0.4 });
    hatchFamily(pc(C.blueV), Fm, { n: 120, steps: 70, shade: sm, vis: vm, thr: 0.55, spread: 0.3, pmin: 0.3, pmax: 0.5, maxLen: 10, t0: 0.02, ph: 0.7 });
