    hatchFamily(P(0.1), Fm, { n: 150, steps: 70, shade: sm, vis: vm, thr: 0.7, spread: 0.26, pmin: 0.4, pmax: 0.7, maxLen: 6, t0: 0.04, ph: 0.2 });
    // the tepals: a vein down the middle of each and fine side veins; seams between them drawn a little firmer
