    contour(sil.right, { nib: (p) => litW(p, BC, 0.2, 0.36), pf: () => 0.9, pull: 10, reg: g });
    { let run = [], wasF = null; const runs = [];
      for (let i = 0; i <= 360; i++) { const th = i / 360 * TAU, f = front(hEnd(th) * 0.99, th); if (wasF !== null && f !== wasF) { runs.push([wasF, run]); run = [run[run.length - 1]]; } run.push(rim[i]); wasF = f; }
      runs.push([wasF, run]);
      for (const [f, r] of runs) if (r.length > 2) contour(r, { nib: f ? 0.32 : 0.16, pressure: 0.9, pull: 9, reg: g }); }
    { const c = B.axis(0.012), e = ellipsePts(c, 1.5, 1.0, 9 * D2R, 16); tint(e, C.leaf, { pressure: 0.5, pitch: 0.35, length: 2 }); contour(closed(e).slice(4, 15), { nib: 0.18, pressure: 0.8 }); }
    // the clapper: a fine style hanging out of the mouth, lagging the swing, ending in a small round bob; two anthers
