    hatchFamily(pc(C.lilac), F, { n: 120, steps: 44, shade: (a, t) => (0.3 + sh(a, t)) * vw(t), vis, thr: 0.12, spread: 0.2, pmin: 0.4, pmax: 0.55, maxLen: 8, ph: 0.6 });
    hatchFamily(pc(C.violet), F, { n: 120, steps: 44, shade: (a, t) => (sh(a, t) + 0.1) * vw(t), vis, thr: 0.4, spread: 0.35, pmin: 0.4, pmax: 0.6, maxLen: 8, ph: 0.15 });
