    const depth = (p) => clamp((p[1] - GY(p[0])) / 22, 0, 1), side = (p) => Math.min(sstep(X0 - 1, X0 + 9, p[0]), 1 - sstep(X1 - 9, X1 + 1, p[0]), 1 - sstep(YB - 8, YB + 0.5, p[1]));
    maskTint(soil, C.soil, (p) => keep(p) && R() < (1 - 0.55 * depth(p)) * side(p) ** 0.7, { angle: 25, pressure: 0.42 });
    maskTint(soil, C.soilD, (p) => keep(p) && depth(p) < 0.35 && R() < 0.8 * side(p), { angle: 70, pressure: 0.35 });
    stipple(soil, (p) => (1 - 0.75 * depth(p)) * 0.9 * side(p) * (0.75 + 0.5 * (0.5 + 0.5 * NZ.n2(p[0] * 0.2, p[1] * 0.2))), { per: 2.2, nib: 0.13, size: 0.85, keep });
    for (let i = 0; i < 260; i++) { const x = lerp(X0 + 1, X1 - 1, R()), y = GY(x) + 0.8 + Math.pow(R(), 1.6) * 20, p = [x, y]; if (!keep(p) || !inPoly(p, soil) || R() > side(p)) continue; const a = (R() - 0.5) * 2.2, l = 0.4 + R() * 0.9, q = addv(p, [Math.cos(a) * l, Math.sin(a) * l]); if (!keep(q)) continue; P(0.1).stroke([p, q], { pressure: 0.75, profile: 'taper' }); }
    for (const s of stones) { tint(s.poly, C.stone, { pressure: 0.45, pitch: 0.45, length: 3 }); P(0.1).hatch(s.poly.filter((p) => facing2(sub(p, s.c)) < 0.2).concat([s.c]), { angle: 50, pitch: 0.42, pressure: 0.7, length: 3 }); contour(closed(s.poly), { nib: (p) => litW(p, s.c, 0.12, 0.2), pressure: 0.85, pull: 6 }); }
    // the ground line with small clods on it; the cut-away's sides fade to nothing (no hard box)
    contour(soil.slice(0, 61), { nib: 0.3, pf: (p, t) => 0.92 * Math.min(1, Math.min(t * 7, (1 - t) * 7)), pull: 12, reg: g });
    for (let i = 0; i < 22; i++) { const x = lerp(X0 + 3, X1 - 3, R()); if (Math.abs(x - SX) < 3) continue; P(0.12).dot([x, GY(x) - 0.4 - R() * 0.3], { size: 0.8 + R() * 0.8, pressure: 0.9 }); }
