      for (let i = 0; i <= n; i++) { const u = i / n, w = lerp(r.w0, r.w1, u) / 2, p = r.sp.pos(u), nn = r.sp.nrm(u); Ls.push(addv(p, mul(nn, w))); Rs.push(addv(p, mul(nn, -w))); }
