  for (const yy of [top + 12, top + 19, top + 27, top + 35, top + 44, top + 51]) ln(.16, [[n.x0 + 1, yy], [n.x0 + 3.2, yy + .5], [n.x0 + 5, yy + .2]], { p: .8, profile: 'taper' });
  ln(.16, [[n.x0 + 3.8, top + 30], [n.x0 + 3.2, top + 34], [n.x0 + 4, top + 38]], { profile: 'taper' });
  // the far hills: lighter, a few strokes only
  for (let k = 1, dd = 1.2; dd < 12; k++, dd += 1.1) { const tau = frac(k * .618 + .4), pts = low.map(([x, y]) => [x, y + dd]).filter(([x, y]) => y < B - .5 && pip([x, y], farP));
    let run = []; for (const q of pts) { if (sm(0, 1, ((q[0] - n.x1) % 34) / 34) > tau * .9 + .1 && q[0] > n.x1 + 29) run.push(q); else { if (run.length > 3) use(ink(.1)).stroke(run, { pressure: .5, smooth: .3, profile: 'taper' }); run = [] } } if (run.length > 3) use(ink(.1)).stroke(run, { pressure: .5, smooth: .3, profile: 'taper' }) }
  ln(.34, sil, { p: .9, smooth: .1 }); ln(.22, spline(rock.slice(0, 5), 4), { p: .8 });
  ln(.2, spline([[n.x1 + 24.6, B - 8], [n.x1 + 26, B - 4.4], [n.x1 + 26.4, B - 1.4]], 4));
  for (const x of [n.x0 + 9, n.x0 + 12.5]) { const y = yAt(brow, x); for (const d of [-.8, 0, .8]) ln(.14, [[x + d * .6, y - .3], [x + d * 1.3, y - 2.4 + Math.abs(d)]], { profile: 'taper' }) }
